    return bytes(b + [n])


strings = ['', 'Probe', 'flash.display', 'Sprite', 'trace', 'graphics', 'beginFill',
           'drawRect', 'endFill', 'addChild', 'hitTestPoint', 'visible', 'alpha',
           'mask', 'removeChild', 'clear', 'lineStyle', 'x', 'y']
