def op(n, *args): return bytes([n]) + b''.join(u(a) for a in args)
def num(n): return op(0x24, n)
def get(n): return bytes([0xd0 + n])
def prop(n): return op(0x66, q[n])
def call(n, c): return op(0x4f, q[n], c)
def setp(n): return op(0x61, q[n])
