export function createProjectile(uid: number, options: Spawn): Projectile {
  return {
    heading: options.angle,
    radius: 2,
    age: 0,
    life: Infinity,
    explode: 0,
    targetId: null,
    hit: new Set(),
    missExempt: options.kind === 'apocalypse' ? true : undefined,
    dead: false,
    artScale: 1,
    orbit: 0,
    ...options,
    uid,
  };
}
